\set ON_ERROR_STOP on
-- Disposable PostgreSQL ONLY. Never run against Neon: it creates objects.
--
-- The pick-writing code AS DEPLOYED, not as written in this repository: the
-- base schema and these functions predate the migrations kept here. Every
-- CREATE FUNCTION below is the exact text returned by pg_get_functiondef on
-- the isolated QA branch the QA branch (project the QA project,
-- PostgreSQL 18.6) on 2026-11-12 between 13:23 and 13:28 UTC. The block at
-- the end fails unless each stored body still has the SHA-256 the catalog
-- reported, so this file cannot drift from what was read.
--
-- pool_platform_create_draft_week is taken from the catalog too: the deployed
-- body is the repository's 20261103_commissioner_draft_week.sql without three
-- comment lines and two blank lines.
--
-- The audit table, the trigger and the Survivor index are written from
-- pg_attribute, pg_constraint, pg_get_triggerdef and pg_get_indexdef read on
-- the same branch at the same time.
--
-- Run after tests/e2e/final-results-e2e-db-fixture.sql, which provides the
-- base tables and the identity stand-in.

CREATE TABLE public.pool_platform_submission_audit(
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  submission_id uuid NOT NULL REFERENCES public.pool_platform_submissions(id) ON DELETE CASCADE,
  actor_auth_user_id text,
  action text NOT NULL CHECK (action = ANY (ARRAY['created'::text, 'updated'::text, 'locked'::text, 'correction'::text])),
  source text NOT NULL CHECK (source = ANY (ARRAY['participant'::text, 'commissioner_import'::text, 'commissioner_manual'::text, 'system'::text])),
  previous_payload jsonb,
  next_payload jsonb,
  reason text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX pool_platform_submissions_survivor_team_unique ON public.pool_platform_submissions USING btree (entry_id, ((payload ->> 'team'::text))) WHERE (jsonb_typeof((payload -> 'team'::text)) = 'string'::text);
-- pool_platform_guard_submission_source: prosrc SHA-256 8292052734241e2f9502e5aa2cd994a948360c1aea6c4c03eacb89af74abce4a
CREATE OR REPLACE FUNCTION public.pool_platform_guard_submission_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='UPDATE' AND NEW.source<>OLD.source THEN
    RAISE EXCEPTION 'submission source is immutable once claimed';
  END IF;
  IF TG_OP='UPDATE' AND OLD.status='locked' THEN
    RAISE EXCEPTION 'locked submission cannot be modified';
  END IF;
  RETURN NEW;
END;
$function$;
CREATE TRIGGER pool_platform_submission_source_guard BEFORE UPDATE ON public.pool_platform_submissions FOR EACH ROW EXECUTE FUNCTION pool_platform_guard_submission_source();
-- pool_platform_payload_valid: prosrc SHA-256 584e061834f72a5671e27fdfe9c840da544f9a0ee791d5af3d094c41a14f2b66
CREATE OR REPLACE FUNCTION public.pool_platform_payload_valid(p_pool_type text, p_week_config jsonb, p_entry_id uuid, p_week_id uuid, p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'neon_auth', 'pg_temp'
AS $function$
DECLARE
  v_required_tb boolean;
  v_tb_text text;
  v_team text;
  v_week integer;
  v_season_id uuid;
BEGIN
  IF p_payload IS NULL OR COALESCE(jsonb_typeof(p_payload),'')<>'object' THEN RETURN false; END IF;

  IF p_pool_type='pickem' THEN
    IF COALESCE(jsonb_typeof(p_week_config->'games'),'')<>'array'
       OR COALESCE(jsonb_typeof(p_payload->'picks'),'')<>'object'
    THEN RETURN false; END IF;

    IF (SELECT count(*) FROM jsonb_array_elements(p_week_config->'games'))=0
       OR (SELECT count(*) FROM jsonb_array_elements(p_week_config->'games'))
          <> (SELECT count(DISTINCT g->>'id') FROM jsonb_array_elements(p_week_config->'games') g)
    THEN RETURN false; END IF;

    -- Fail closed: every configured game needs a nonempty id and a JSON string pick of exactly
    -- 'away' or 'home'. A missing or JSON-null pick makes the inner expression NULL, which
    -- COALESCE turns into false, so the game is rejected instead of skipped.
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_week_config->'games') g
      WHERE NOT COALESCE(
        jsonb_typeof(g)='object'
        AND jsonb_typeof(g->'id') IN ('string','number')
        AND (g->>'id')<>''
        AND jsonb_typeof(p_payload->'picks'->(g->>'id'))='string'
        AND (p_payload->'picks'->>(g->>'id')) IN ('away','home'),
        false
      )
    ) THEN RETURN false; END IF;

    IF EXISTS (
      SELECT 1
      FROM jsonb_object_keys(p_payload->'picks') k
      WHERE NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(p_week_config->'games') g
        WHERE g->>'id'=k
      )
    ) THEN RETURN false; END IF;

    IF EXISTS (
      SELECT 1 FROM jsonb_object_keys(p_payload) k
      WHERE k NOT IN ('picks','tiebreak')
    ) THEN RETURN false; END IF;

    v_required_tb:=lower(COALESCE(p_week_config->>'tiebreakRequired',p_week_config->>'tiebreak_required','false'))='true';
    v_tb_text:=p_payload->>'tiebreak';
    IF v_required_tb OR v_tb_text IS NOT NULL THEN
      IF v_tb_text IS NULL OR v_tb_text!~'^[0-9]{1,3}$' THEN RETURN false; END IF;
      IF v_tb_text::integer>200 THEN RETURN false; END IF;
    END IF;
    RETURN true;
  END IF;

  IF p_pool_type='survivor' THEN
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(p_payload) k WHERE k<>'team')
    THEN RETURN false; END IF;
    -- The team must be a JSON string. ->> renders a number, boolean, array or object as text that can still
    -- equal a configured key, and pool_platform_submissions_survivor_team_unique only covers string teams,
    -- so a non-string pick would get past the index; it is rejected before any key, history or index logic.
    IF COALESCE(jsonb_typeof(p_payload->'team'),'')<>'string' THEN RETURN false; END IF;
    v_team:=NULLIF(p_payload->>'team','');
    IF v_team IS NULL OR COALESCE(jsonb_typeof(p_week_config->'games'),'')<>'array'
    THEN RETURN false; END IF;

    IF (
      SELECT count(*)
      FROM (
        SELECT COALESCE(NULLIF(g->'away'->>'key',''),NULLIF(g->>'away','')) AS team
        FROM jsonb_array_elements(p_week_config->'games') g
        UNION ALL
        SELECT COALESCE(NULLIF(g->'home'->>'key',''),NULLIF(g->>'home','')) AS team
        FROM jsonb_array_elements(p_week_config->'games') g
      ) teams
      WHERE team=v_team
    )<>1 THEN RETURN false; END IF;

    SELECT w.week,w.season_id INTO v_week,v_season_id
    FROM public.pool_platform_weeks w WHERE w.id=p_week_id;
    IF v_week IS NULL THEN RETURN false; END IF;

    -- Defense in depth behind pool_platform_submissions_survivor_team_unique: the team must be unused by
    -- this entry in every OTHER week of the season, earlier or later, so out-of-order submissions are
    -- caught too. Only a structurally valid pick gets here; reuse raises team_already_used instead of
    -- returning false so submit_entry can tell an authorized caller exactly why it was rejected.
    IF EXISTS (
      SELECT 1
      FROM public.pool_platform_submissions s
      JOIN public.pool_platform_weeks w ON w.id=s.week_id
      WHERE s.entry_id=p_entry_id
        AND w.season_id=v_season_id
        AND s.week_id<>p_week_id
        AND s.payload->>'team'=v_team
    ) THEN RAISE EXCEPTION 'team_already_used'; END IF;
    RETURN true;
  END IF;

  RETURN false;
END;
$function$;
-- pool_platform_submit_entry: prosrc SHA-256 f52183734e1f8c42c401e2a507e8c82323c259486909adca49d9537eed523c8f
CREATE OR REPLACE FUNCTION public.pool_platform_submit_entry(p_week_id uuid, p_entry_id uuid, p_source text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'neon_auth', 'pg_temp'
AS $function$
DECLARE
  v_uid text:=public.pool_platform_current_user_id();
  v_tenant_id uuid;
  v_owner text;
  v_entry_status text;
  v_week_id uuid;
  v_week_status text;
  v_opens timestamptz;
  v_deadline timestamptz;
  v_pool_type text;
  v_week_config jsonb;
  v_existing public.pool_platform_submissions%ROWTYPE;
  v_created public.pool_platform_submissions%ROWTYPE;
  v_previous_payload jsonb;
  v_constraint text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF p_source IS NULL OR p_source NOT IN ('participant','commissioner_import','commissioner_manual')
  THEN RAISE EXCEPTION 'invalid_source'; END IF;

  -- Resolve and lock the entry row with its season, pool and tenant, whatever week was asked for: every
  -- submission for one entry (any week, any source) queues here, so the Survivor reuse check reads that
  -- entry's committed history. The unique index pool_platform_submissions_survivor_team_unique still
  -- guarantees the outcome on its own. The requested week is joined only within the entry's own season,
  -- and whether it matched is looked at only once the caller is authorized.
  SELECT p.tenant_id,e.owner_auth_user_id,e.status,w.id,w.status,w.opens_at,w.deadline_at,p.pool_type,w.config
  INTO v_tenant_id,v_owner,v_entry_status,v_week_id,v_week_status,v_opens,v_deadline,v_pool_type,v_week_config
  FROM public.pool_platform_entries e
  JOIN public.pool_platform_seasons s ON s.id=e.season_id
  JOIN public.pool_platform_pools p ON p.id=s.pool_id
  LEFT JOIN public.pool_platform_weeks w ON w.id=p_week_id AND w.season_id=s.id
  WHERE e.id=p_entry_id
  FOR NO KEY UPDATE OF e;

  -- Authorize before the week or any entry-state, week-state, payload or history check, so a caller who is
  -- not the entry owner (participant) or a commissioner of the entry's tenant (commissioner sources) only
  -- ever sees that failure: it does not tell whether the entry exists or whether the week belongs to it. A
  -- missing entry has no owner and no tenant, so it fails the same way.
  IF p_source='participant' THEN
    IF v_owner IS NULL OR v_owner<>v_uid THEN RAISE EXCEPTION 'entry_not_owned'; END IF;
  ELSE
    IF v_tenant_id IS NULL OR NOT public.pool_platform_is_tenant_commissioner(v_tenant_id)
    THEN RAISE EXCEPTION 'commissioner_required'; END IF;
  END IF;

  -- Only an authorized caller learns whether the week belongs to the entry's season.
  IF v_week_id IS NULL THEN RAISE EXCEPTION 'invalid_entry_week'; END IF;

  -- Ordinary submissions need an active entry; inactive, eliminated and archived entries are closed.
  IF v_entry_status IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'entry_not_active'; END IF;

  IF v_week_status<>'open' THEN RAISE EXCEPTION 'week_not_open'; END IF;
  IF v_opens IS NOT NULL AND now()<v_opens THEN RAISE EXCEPTION 'week_not_open'; END IF;
  IF now()>=v_deadline THEN RAISE EXCEPTION 'deadline_passed'; END IF;

  IF p_payload IS NULL OR COALESCE(jsonb_typeof(p_payload),'')<>'object' OR octet_length(p_payload::text)>20000
  THEN RAISE EXCEPTION 'invalid_payload'; END IF;
  IF NOT public.pool_platform_payload_valid(v_pool_type,v_week_config,p_entry_id,p_week_id,p_payload)
  THEN RAISE EXCEPTION 'invalid_payload'; END IF;

  INSERT INTO public.pool_platform_submissions(
    week_id,entry_id,source,status,submitted_by_auth_user_id,payload,revision,submitted_at,updated_at
  ) VALUES (
    p_week_id,p_entry_id,p_source,'submitted',v_uid,p_payload,1,now(),now()
  )
  ON CONFLICT (week_id,entry_id) DO NOTHING
  RETURNING * INTO v_created;

  IF v_created.id IS NOT NULL THEN
    INSERT INTO public.pool_platform_submission_audit(
      submission_id,actor_auth_user_id,action,source,previous_payload,next_payload
    ) VALUES (v_created.id,v_uid,'created',p_source,NULL,p_payload);
    RETURN jsonb_build_object(
      'ok',true,'code','created','submission_id',v_created.id,
      'source',v_created.source,'status',v_created.status,'revision',v_created.revision
    );
  END IF;

  SELECT * INTO v_existing
  FROM public.pool_platform_submissions
  WHERE week_id=p_week_id AND entry_id=p_entry_id
  FOR UPDATE;

  IF v_existing.source<>p_source
  THEN RAISE EXCEPTION 'source_conflict:%',v_existing.source; END IF;
  IF v_existing.status='locked'
  THEN RAISE EXCEPTION 'submission_locked'; END IF;

  v_previous_payload:=v_existing.payload;

  UPDATE public.pool_platform_submissions
  SET payload=p_payload,revision=revision+1,submitted_by_auth_user_id=v_uid,updated_at=now()
  WHERE id=v_existing.id
  RETURNING * INTO v_existing;

  INSERT INTO public.pool_platform_submission_audit(
    submission_id,actor_auth_user_id,action,source,previous_payload,next_payload
  ) VALUES (v_existing.id,v_uid,'updated',p_source,v_previous_payload,p_payload);

  RETURN jsonb_build_object(
    'ok',true,'code','updated','submission_id',v_existing.id,
    'source',v_existing.source,'status',v_existing.status,'revision',v_existing.revision
  );
EXCEPTION WHEN unique_violation THEN
  -- The Survivor team index can only be violated by the INSERT/UPDATE above; report it plainly.
  GET STACKED DIAGNOSTICS v_constraint=CONSTRAINT_NAME;
  IF v_constraint='pool_platform_submissions_survivor_team_unique'
  THEN RAISE EXCEPTION 'team_already_used'; END IF;
  RAISE;
END;
$function$;
-- pool_platform_submit_batch: prosrc SHA-256 d8738a157683c5a35d899c496bea78a2bc32a651686856f999402d47ab66098c
CREATE OR REPLACE FUNCTION public.pool_platform_submit_batch(p_week_id uuid, p_source text, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'neon_auth', 'pg_temp'
AS $function$
DECLARE
  v_uid text:=public.pool_platform_current_user_id();
  v_tenant_id uuid;
  v_item jsonb;
  v_result jsonb:='[]'::jsonb;
  v_one jsonb;
  v_entry uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF p_source NOT IN ('commissioner_import','commissioner_manual')
  THEN RAISE EXCEPTION 'commissioner_source_required'; END IF;
  IF jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)>500
  THEN RAISE EXCEPTION 'invalid_batch'; END IF;

  SELECT p.tenant_id INTO v_tenant_id
  FROM public.pool_platform_weeks w
  JOIN public.pool_platform_seasons s ON s.id=w.season_id
  JOIN public.pool_platform_pools p ON p.id=s.pool_id
  WHERE w.id=p_week_id;

  IF v_tenant_id IS NULL OR NOT public.pool_platform_is_tenant_commissioner(v_tenant_id)
  THEN RAISE EXCEPTION 'commissioner_required'; END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    BEGIN
      v_entry:=(v_item->>'entry_id')::uuid;
      v_one:=public.pool_platform_submit_entry(
        p_week_id,v_entry,p_source,COALESCE(v_item->'payload','{}'::jsonb)
      );
      v_result:=v_result||jsonb_build_array(
        jsonb_build_object('entry_id',v_entry,'ok',true,'result',v_one)
      );
    EXCEPTION WHEN OTHERS THEN
      v_result:=v_result||jsonb_build_array(
        jsonb_build_object(
          'entry_id',COALESCE(v_item->>'entry_id',''),
          'ok',false,'code',SQLERRM
        )
      );
    END;
  END LOOP;

  RETURN v_result;
END;
$function$;
-- pool_platform_create_draft_week: prosrc SHA-256 a14b613ec12e44d81be8e55990cfa05991d834422389b2924399af106892cf95
CREATE OR REPLACE FUNCTION public.pool_platform_create_draft_week(p_season_id uuid, p_week integer, p_deadline_at timestamp with time zone, p_opens_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'neon_auth', 'pg_temp'
AS $function$
DECLARE
  v_uid text := public.pool_platform_current_user_id();
  v_tenant_id uuid;
  v_id uuid;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF;
  IF p_week IS NULL OR p_week NOT BETWEEN 1 AND 25
    THEN RAISE EXCEPTION 'invalid_week_number'; END IF;
  IF p_deadline_at IS NULL
    OR p_deadline_at <= clock_timestamp() + interval '5 minutes'
    OR p_deadline_at > clock_timestamp() + interval '18 months'
    THEN RAISE EXCEPTION 'invalid_week_deadline'; END IF;
  IF p_opens_at IS NOT NULL AND p_opens_at >= p_deadline_at
    THEN RAISE EXCEPTION 'invalid_week_opening'; END IF;
  SELECT p.tenant_id INTO v_tenant_id
  FROM public.pool_platform_seasons s
  JOIN public.pool_platform_pools p ON p.id = s.pool_id
  JOIN public.pool_platform_tenants t ON t.id = p.tenant_id
  WHERE s.id = p_season_id
    AND s.status IN ('setup', 'active')
    AND p.status = 'active'
    AND t.status = 'active';
  IF v_tenant_id IS NULL OR NOT public.pool_platform_is_tenant_commissioner(v_tenant_id)
    THEN RAISE EXCEPTION 'commissioner_required'; END IF;
  IF EXISTS(SELECT 1 FROM public.pool_platform_weeks w
            WHERE w.season_id=p_season_id AND w.week=p_week)
    THEN RAISE EXCEPTION 'duplicate_week_number'; END IF;
  INSERT INTO public.pool_platform_weeks(season_id,week,status,opens_at,deadline_at,config)
  VALUES(p_season_id,p_week,'draft',p_opens_at,p_deadline_at,'{"games":[]}'::jsonb)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id',v_id,'week',p_week,'status','draft','deadline_at',p_deadline_at);
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'duplicate_week_number';
END;
$function$;
-- Execute privileges as the catalog reported them: three RPCs for signed-in
-- users, the two helpers for nobody but the owner.
REVOKE ALL ON FUNCTION public.pool_platform_guard_submission_source() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pool_platform_payload_valid(text,jsonb,uuid,uuid,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pool_platform_submit_entry(uuid,uuid,text,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pool_platform_submit_batch(uuid,text,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.pool_platform_create_draft_week(uuid,integer,timestamptz,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.pool_platform_submit_entry(uuid,uuid,text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.pool_platform_submit_batch(uuid,text,jsonb) TO authenticated;
GRANT EXECUTE ON FUNCTION public.pool_platform_create_draft_week(uuid,integer,timestamptz,timestamptz) TO authenticated;

DO $same_as_deployed$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('pool_platform_guard_submission_source','8292052734241e2f9502e5aa2cd994a948360c1aea6c4c03eacb89af74abce4a'),
    ('pool_platform_payload_valid','584e061834f72a5671e27fdfe9c840da544f9a0ee791d5af3d094c41a14f2b66'),
    ('pool_platform_submit_entry','f52183734e1f8c42c401e2a507e8c82323c259486909adca49d9537eed523c8f'),
    ('pool_platform_submit_batch','d8738a157683c5a35d899c496bea78a2bc32a651686856f999402d47ab66098c'),
    ('pool_platform_create_draft_week','a14b613ec12e44d81be8e55990cfa05991d834422389b2924399af106892cf95')
  ) AS expected(fn,sha256) LOOP
    IF (SELECT encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') FROM pg_proc p
        WHERE p.pronamespace='public'::regnamespace AND p.proname=r.fn) IS DISTINCT FROM r.sha256
    THEN RAISE EXCEPTION 'the stored body of % is not the body read from the QA catalog', r.fn; END IF;
  END LOOP;
END;
$same_as_deployed$;
\echo DEPLOYED_SUBMISSION_PATHS_LOADED
